<?php
/** SQL-read volume fixture, rolled back in full. Not a simulation of 10k owner commands. */
function mg_volume($q,$nativeId): void {
    global $wpdb;$db=$q->db;$native=$db->row($db->prepare('SELECT * FROM '.$db->table('native_executions').' WHERE id=%s',$nativeId));$binding=json_decode($native['binding_json'],true);$source=$binding['execution_id'];$opportunity=$binding['block_execution_id'];
    $digits='(SELECT 0 AS n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9)';$numbers='(SELECT a.n+10*b.n+100*c.n+1000*d.n AS n FROM '.$digits.' a CROSS JOIN '.$digits.' b CROSS JOIN '.$digits.' c CROSS JOIN '.$digits.' d) nums';
    $measurements=array();
    try{$db->transactional(function()use($db,$q,$source,$opportunity,$nativeId,$numbers,&$measurements,$wpdb){
        $previous=0;foreach(array(100,1000,10000) as $target){
            foreach(array('study_executions','block_executions','native_executions') as $table){
                $sourceId=$table==='study_executions'?$source:($table==='block_executions'?$opportunity:$nativeId);$row=$db->row($db->prepare('SELECT * FROM '.$db->table($table).' WHERE id=%s',$sourceId));unset($row['management_execution'],$row['management_opportunity']);$cols=array();$select=array();
                foreach($row as $col=>$value){$cols[]='`'.$col.'`';$suffix=$table==='study_executions'?'nums.n':'(nums.n*2+op.n)';$expression='s.`'.$col.'`';if($col==='id')$expression="CONCAT('MGV_".$table."_',".$suffix.")";if($table==='study_executions'&&$col==='create_key')$expression="SHA2(CONCAT('MGV_REQ_',nums.n),256)";if($col==='execution_id')$expression="CONCAT('MGV_study_executions_',nums.n)";if($table==='native_executions'&&$col==='binding_json')$expression="JSON_SET(s.binding_json,'$.execution_id',CONCAT('MGV_study_executions_',nums.n),'$.block_execution_id',CONCAT('MGV_block_executions_',nums.n*2+op.n))";if($table==='block_executions'&&$col==='occurrence_hash')$expression="SHA2(CONCAT(s.occurrence_hash,op.n),256)";$select[]=$expression;}
                $db->query('INSERT INTO '.$db->table($table).' ('.implode(',',$cols).') SELECT '.implode(',',$select).' FROM '.$db->table($table).' s CROSS JOIN '.$numbers.($table==='study_executions'?'':' CROSS JOIN (SELECT 0 AS n UNION ALL SELECT 1) op').$db->prepare(' WHERE s.id=%s AND nums.n>=%d AND nums.n<%d',$sourceId,$previous,$target));
            }
            $before=$wpdb->num_queries;$start=microtime(true);$memory=memory_get_usage(true);$fresh=new EIPSI\StudyEngine\Management\Query($q->study);$timing=array();$mark=microtime(true);$summary=$fresh->summary(array());$timing['summary']=round(microtime(true)-$mark,4);$mark=microtime(true);$participants=$fresh->participants(array());$timing['participants']=round(microtime(true)-$mark,4);$mark=microtime(true);$opportunities=$fresh->opportunities(array());$timing['opportunities']=round(microtime(true)-$mark,4);$mark=microtime(true);$attempts=$fresh->attempts(array());$timing['attempts']=round(microtime(true)-$mark,4);$elapsed=microtime(true)-$start;$queries=$wpdb->num_queries-$before;
            pe_assert($summary['counts']['participations']===$target+1,'Volume count');pe_assert(count($participants['items'])===25&&count($opportunities['items'])===25&&count($attempts['items'])===25,'Bounded pages');pe_assert($queries<=20,'N+1 in dashboard');pe_assert($elapsed<10,'Dashboard query budget');$measurements[]=array('participations'=>$target,'seconds'=>round($elapsed,4),'queries'=>$queries,'allocated_delta_bytes'=>max(0,memory_get_usage(true)-$memory),'timing'=>$timing,'page_size'=>25,'native_opportunities'=>2*$target);$previous=$target;
        }
        $explain=$db->rows($db->prepare('EXPLAIN SELECT id FROM '.$db->table('native_executions').' WHERE management_execution=%s',$source));pe_assert(strpos($explain[0]['possible_keys']??'','management_binding')!==false,'Native index unavailable');echo 'VOLUME '.json_encode($measurements)."\n";throw new RuntimeException('VOLUME_ROLLBACK');
    });}catch(RuntimeException $e){if($e->getMessage()!=='VOLUME_ROLLBACK')throw $e;}
    pe_assert($q->summary(array())['counts']['participations']===1,'Volume fixture leaked');
}
